from collections import deque

def solve_maze(maze):
    """
    Solve maze using BFS with state = (row, col, frozenset of keys collected)
    """
    start = (0, 0)
    goal = (11, 11)

    # State: (row, col, keys_collected_as_frozenset)
    initial_state = (0, 0, frozenset())

    queue = deque([(initial_state, [start])])
    visited = {initial_state}

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    while queue:
        (row, col, keys), path = queue.popleft()

        # Check if we reached goal with all keys
        if (row, col) == goal and len(keys) == 4:
            return path

        # Explore neighbors
        for dr, dc in directions:
            nr, nc = row + dr, col + dc

            # Boundary check
            if not (0 <= nr < 12 and 0 <= nc < 12):
                continue

            cell = maze[nr][nc]

            # Wall check
            if cell == 1:
                continue

            # Door check - can only pass if we have the key
